column5:
It would actually creep me out to get any other result.<p>For his desired outcome on the ES4 command line:<p><pre><code>  var message = "Hello";
  var blah0 = function () {
                  var x = message;
                  return function () {
                      print(x);
                  }
              }();
  message = "World!";
  var blah1 = function () {
                  var x = message;
                  return function () {
                      print(x);
                  }
              }();
  blah0();
  >> Hello
  blah1();
  >> World!</code></pre>
